def grade(m):
    if m >= 90:
        return 'A'
    elif m >= 75:
        return 'B'
    elif m >= 60:
        return 'C'
    elif m >= 40:
        return 'D'
    return 'F'

n = int(input())
students = []
for _ in range(n):
    name, marks = input().split()
    students.append((name, int(marks)))

if not students:
    print('No students')
else:
    for name, marks in students:
        print(f'{name}: {grade(marks)}')
    average = sum(m for _, m in students) / len(students)
    print(f'Average: {average:.2f}')
    top_name, top_marks = students[0]
    for name, marks in students[1:]:
        if marks > top_marks:
            top_name, top_marks = name, marks
    print(f'Topper: {top_name} ({top_marks})')

